CREATE FUNCTION public.get_home_expense_context() RETURNS TABLE(shop_id uuid, recurring_source text, fixed_weekly_expenses_cents integer) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$ DECLARE selected_shop uuid := public.current_shop_id(); BEGIN IF selected_shop IS NULL OR NOT (public.has_shop_role(selected_shop,'owner') OR public.has_shop_role(selected_shop,'super_owner')) THEN RAISE EXCEPTION 'permission denied: home expenses'; END IF; RETURN QUERY SELECT selected_shop, COALESCE(h.recurring_source,'legacy'), COALESCE((SELECT s.fixed_weekly_expenses_cents FROM public.shop_settings s WHERE s.shop_id=selected_shop ORDER BY s.created_at LIMIT 1),0) FROM (SELECT 1) seed LEFT JOIN public.home_expense_settings h ON h.shop_id=selected_shop; END; $$;
REVOKE ALL ON FUNCTION public.get_home_expense_context() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_home_expense_context() TO authenticated, service_role;